import AppKit
import Combine

/// Text clipboard history, kept in memory only (never written to disk).
/// Skips items that password managers mark as concealed/transient.
@MainActor
final class ClipboardHistory: ObservableObject {
    struct Item: Identifiable, Equatable {
        let id = UUID()
        let text: String
        let date: Date
    }

    static let shared = ClipboardHistory(pasteboard: .general)
    static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]

    @Published private(set) var items: [Item] = []
    let pasteboard: NSPasteboard
    var maxItems = 30
    private var lastChange: Int
    private var timer: Timer?

    init(pasteboard: NSPasteboard) {
        self.pasteboard = pasteboard
        lastChange = pasteboard.changeCount // start from now; existing clipboard is not imported
    }

    var isActive: Bool { timer != nil }

    func setActive(_ on: Bool) {
        guard on != isActive else { return }
        if on {
            lastChange = pasteboard.changeCount
            timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in
                MainActor.assumeIsolated { self?.poll() }
            }
        } else {
            timer?.invalidate()
            timer = nil
        }
    }

    func poll() {
        let change = pasteboard.changeCount
        guard change != lastChange else { return }
        lastChange = change
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.skippedTypes) else { return }
        guard let s = pasteboard.string(forType: .string),
              !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        add(s)
    }

    private func add(_ s: String) {
        items.removeAll { $0.text == s }
        items.insert(Item(text: s, date: Date()), at: 0)
        if items.count > maxItems { items.removeLast(items.count - maxItems) }
    }

    /// Put an item back on the clipboard (and move it to the top).
    func copy(_ item: Item) {
        pasteboard.clearContents()
        pasteboard.setString(item.text, forType: .string)
        lastChange = pasteboard.changeCount
        add(item.text)
    }

    func clear() { items = [] }
}
